questionvariables.text:
/* Randomly generate an integer from 1 to 11 */
k: 1+rand(11);

/* Generate the angle in radians */
angle_rad: k*%pi/6;

/* Conversion factor from radians to degrees */
conversion_factor: 180;

/* Calculate the equivalent angle in degrees */
angle_deg: k*conversion_factor/6;

/* Teacher answer */
ta: angle_deg;
